shared_html.shared_css:
/* ============================================================
   Shared nav + footer — Hokurin Daigaku
   ============================================================ */

.site-nav,
.site-footer {
  font-family: "Inter", system-ui, sans-serif;
  color: var(--text);
  background: var(--bg);
}

/* ---------- HEADER ---------- */

.site-nav {
  position: relative;
  padding: 1.75rem 0 0;
  border-top: 4px solid var(--primary);
}

.site-nav__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 2.5rem 1.25rem;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 2.5rem;
}

.site-nav__brand {
  display: flex;
  align-items: center;
  gap: 0.9rem;
  text-decoration: none;
  color: var(--primary);
}

.site-nav__seal {
  color: var(--accent);
  display: inline-flex;
}

.site-nav__wordmark {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.site-nav__wordmark-jp {
  font-family: "Shippori Mincho", serif;
  font-weight: 700;
  font-size: 1.35rem;
  letter-spacing: 0.08em;
  color: var(--primary);
}

.site-nav__wordmark-en {
  font-size: 0.7rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin-top: 0.2rem;
}

.site-nav__links {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 1.75rem;
}

.site-nav__links a {
  position: relative;
  display: inline-flex;
  align-items: baseline;
  gap: 0.45rem;
  font-size: 0.82rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--primary);
  padding-bottom: 0.4rem;
  transition: color 0.2s ease;
}

.site-nav__links a::after {
  content: "";
  position: absolute;
  left: 0;
  right: 100%;
  bottom: 0;
  height: 1px;
  background: var(--accent);
  transition: right 0.25s ease;
}

.site-nav__links a:hover {
  color: var(--text-emphasis);
}

.site-nav__links a:hover::after {
  right: 0;
}

.site-nav__num {
  font-family: "Shippori Mincho", serif;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--accent);
  letter-spacing: 0;
}

.site-nav__meta {
  display: flex;
  gap: 0.6rem;
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  white-space: nowrap;
}

.site-nav__divider {
  opacity: 0.5;
}

.site-nav__rule {
  height: 1px;
  background: var(--primary);
  opacity: 0.18;
  margin: 0 2.5rem;
}

/* ---------- FOOTER ---------- */

.site-footer {
  margin-top: 6rem;
  padding: 4rem 0 2rem;
  border-top: 1px solid var(--primary);
  position: relative;
}

.site-footer::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 28px;
  background-image: url("svg/seigaiha-waves.svg");
  background-repeat: repeat-x;
  background-size: 96px 28px;
  opacity: 0.12;
  pointer-events: none;
}

.site-footer__inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 2.5rem;
}

.site-footer__signature {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 2rem;
  align-items: start;
  padding-bottom: 2.5rem;
  border-bottom: 1px solid rgba(12, 12, 12, 0.18);
}

.site-footer__seal {
  color: var(--accent);
  display: inline-flex;
}

.site-footer__address {
  font-size: 0.88rem;
  line-height: 1.85;
  color: var(--text);
}

.site-footer__address p {
  margin: 0;
}

.site-footer__name {
  font-family: "Shippori Mincho", serif;
  font-weight: 700;
  font-size: 1.15rem !important;
  letter-spacing: 0.06em;
  color: var(--primary);
  margin-bottom: 0.4rem !important;
}

.site-footer__cols {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 3rem;
  padding: 2.75rem 0;
}

.site-footer__col h4 {
  font-family: "Shippori Mincho", serif;
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin: 0 0 1.1rem;
  padding-bottom: 0.6rem;
  border-bottom: 1px solid var(--primary);
}

.site-footer__col ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer__col li {
  font-size: 0.85rem;
  line-height: 1.85;
  color: var(--text);
}

.site-footer__col a {
  color: var(--text);
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: border-color 0.2s ease, color 0.2s ease;
}

.site-footer__col a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.site-footer__base {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  padding-top: 1.75rem;
  border-top: 1px solid rgba(12, 12, 12, 0.18);
  font-size: 0.72rem;
  letter-spacing: 0.06em;
  color: var(--text);
  opacity: 0.78;
}

.site-footer__colophon,
.site-footer__attribution {
  margin: 0;
}

.site-footer__attribution {
  font-style: italic;
  opacity: 0.85;
}

/* ---------- RESPONSIVE ---------- */

@media (max-width: 900px) {
  .site-nav__inner {
    grid-template-columns: 1fr;
    gap: 1.25rem;
  }
  .site-nav__links {
    justify-content: flex-start;
    gap: 1.25rem;
  }
  .site-nav__meta {
    justify-content: flex-start;
  }
  .site-footer__cols {
    grid-template-columns: 1fr;
    gap: 2rem;
  }
  .site-footer__signature {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 540px) {
  .site-nav__links {
    gap: 0.9rem;
  }
  .site-nav__links a {
    font-size: 0.74rem;
    letter-spacing: 0.1em;
  }
}
